import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'package:path/path.dart' as p;
import 'runtime.dart';

String get design => p.join(root, 'packages/edaya_shared/design-system');
String title(String name) => '${name[0].toUpperCase()}${name.substring(1)}';
String camel(String name) {
  final parts = name.split('-');
  return parts.first + parts.skip(1).map(title).join();
}

String tokenDart(Map<String, dynamic> tokens) {
  final lines = [
    '// Generated by dart run edaya_repo:repo generate brand. Edit the manifest.',
    "import 'package:flutter/material.dart';",
    '',
    'abstract final class EdayaTokens {',
    "  static const version = '${tokens['version']}';",
  ];
  for (final mode in (tokens['colors'] as Map).entries) {
    for (final color in (mode.value as Map).entries) {
      lines.add(
        '  static const ${mode.key}${title(camel(color.key as String))} = Color(0xFF${(color.value as String).substring(1)});',
      );
    }
  }
  for (final group in ['type', 'space', 'radius', 'motion']) {
    for (final entry in (tokens[group] as Map).entries) {
      lines.add(
        '  static const $group${title(entry.key as String)} = ${entry.value}.0;',
      );
    }
  }
  lines.addAll([
    "  static const headingFont = 'Poppins';",
    "  static const bodyFont = 'Inter';",
    '}',
    '',
  ]);
  return lines.join('\n');
}

void brandTokens({bool check = false}) {
  final expected = tokenDart(jsonFile(p.join(design, 'tokens.json')));
  final output = File(
    p.join(root, 'packages/edaya_shared/lib/src/app/edaya_tokens.g.dart'),
  );
  if (check) {
    if (!output.existsSync() || output.readAsStringSync() != expected) {
      throw StateError('Brand token drift');
    }
  } else {
    output.parent.createSync(recursive: true);
    output.writeAsStringSync(expected);
  }
}

double contrast(String a, String b) {
  double luminance(String color) => [1, 3, 5]
      .asMap()
      .entries
      .map((entry) {
        final value =
            int.parse(
              color.substring(entry.value, entry.value + 2),
              radix: 16,
            ) /
            255;
        return (value <= .04045
                ? value / 12.92
                : pow((value + .055) / 1.055, 2.4)) *
            [.2126, .7152, .0722][entry.key];
      })
      .reduce((a, b) => a + b)
      .toDouble();
  final x = luminance(a), y = luminance(b);
  return (max(x, y) + .05) / (min(x, y) + .05);
}

void brandCheck({bool recordReviewedBaseline = false}) {
  brandTokens(check: true);
  final tokens = jsonFile(p.join(design, 'tokens.json')),
      allowed = jsonFile(p.join(design, 'visual-literals.json')),
      expected = jsonFile(p.join(design, 'assets.json'));
  final actual = <String, String>{};
  for (final directory in [
    'packages/edaya_shared/assets',
    'packages/edaya_shared/design-system/logos',
    'branding/icons',
    for (final path in applicationPaths.values) ...[
      '$path/android/app/src/main/res',
      '$path/ios/Runner/Assets.xcassets',
      '$path/web/icons',
      '$path/web/favicon.png',
    ],
  ]) {
    final input = p.join(root, directory);
    for (final file
        in (File(input).existsSync() ? [File(input)] : files(input)).where(
          (file) => !p.basename(file.path).startsWith('.'),
        )) {
      actual[p.relative(file.path, from: root)] = digest(
        file.readAsBytesSync(),
      );
    }
  }
  if (!recordReviewedBaseline &&
      (actual.length != expected.length ||
          actual.entries.any((entry) => expected[entry.key] != entry.value))) {
    throw StateError('Brand asset inventory drift');
  }
  for (final font in [
    'Inter-Regular.ttf',
    'Inter-Medium.ttf',
    'Inter-SemiBold.ttf',
    'Inter-Bold.ttf',
    'Poppins-SemiBold.ttf',
    'Inter-OFL.txt',
    'Poppins-OFL.txt',
  ]) {
    if (!actual.keys.any((key) => key.endsWith('/$font'))) {
      throw StateError('Missing font/license $font');
    }
  }
  final literals = <String, int>{};
  for (final directory in [
    for (final path in applicationPaths.values) '$path/lib',
    'packages/edaya_shared/lib',
  ]) {
    for (final file in files(p.join(root, directory)).where(
      (file) =>
          file.path.endsWith('.dart') &&
          !file.path.contains('/l10n/') &&
          !file.path.endsWith('/edaya_tokens.g.dart'),
    )) {
      final text = file.readAsStringSync();
      if (RegExp(
        r'fonts\.googleapis|GoogleFonts\.|package:google_fonts|Fraunces|Nunito|GalakRound|JetBrains',
      ).hasMatch(text)) {
        throw StateError(
          'Invalid typography: ${p.relative(file.path, from: root)}',
        );
      }
      final counts = <String, int>{};
      for (final match in visualLiteral.allMatches(text)) {
        final key = '${p.relative(file.path, from: root)}::${match[0]}';
        counts[key] = (counts[key] ?? 0) + 1;
      }
      literals.addAll(counts);
      if (!recordReviewedBaseline &&
          counts.entries.any(
            (entry) => entry.value > (allowed[entry.key] as int? ?? 0),
          )) {
        throw StateError(
          'Unreviewed visual literals: ${p.relative(file.path, from: root)}',
        );
      }
    }
  }
  for (final colors in (tokens['colors'] as Map).values) {
    for (final pair in [
      ['foreground', 'background'],
      ['foreground', 'card'],
      ['muted-foreground', 'card'],
      ['muted-foreground', 'background'],
      ['primary-foreground', 'primary'],
      ['highlight', 'highlight-soft'],
      ['success', 'success-soft'],
      ['destructive', 'destructive-soft'],
      ['sky', 'sky-soft'],
    ]) {
      if (contrast(colors[pair[0]] as String, colors[pair[1]] as String) <
          4.5) {
        throw StateError('Text contrast below 4.5:1');
      }
    }
    if (contrast(colors['input'] as String, colors['card'] as String) < 3) {
      throw StateError('Control contrast below 3:1');
    }
  }
  if (recordReviewedBaseline) {
    writeJson(p.join(design, 'assets.json'), actual);
    writeJson(p.join(design, 'visual-literals.json'), literals);
  }
}

Future<void> brandGallery() async {
  final revision = await run(['git', 'rev-parse', 'HEAD'], quiet: true);
  final tokens = jsonFile(p.join(design, 'tokens.json'));
  final inputs = [
    for (final path in applicationPaths.values) '$path/lib',
    'packages/edaya_shared/lib',
    'packages/edaya_shared/assets',
    'packages/edaya_shared/design-system/tokens.json',
  ];
  final source = <int>[];
  for (final input in inputs) {
    for (final file
        in File(p.join(root, input)).existsSync()
            ? [File(p.join(root, input))]
            : files(p.join(root, input))) {
      source.addAll(utf8.encode('${p.relative(file.path, from: root)}\u0000'));
      source.addAll(file.readAsBytesSync());
    }
  }
  final sourceDigest = digest(source);
  for (final entry in applicationPaths.entries) {
    final app = entry.key, path = entry.value;
    final directory = p.join(root, '$path/design-review');
    final manifest = File(p.join(directory, 'manifest.json'));
    final previous = manifest.existsSync()
        ? (jsonFile(manifest.path)['captures'] as List)
        : <dynamic>[];
    final captures = <Map<String, dynamic>>[];
    for (final file in files(
      p.join(directory, 'current'),
    ).where((file) => file.path.endsWith('.png'))) {
      final bytes = file.readAsBytesSync(),
          checksum = digest(file.readAsBytesSync()),
          name = p.basename(file.path),
          relative = 'current/${p.basename(file.path)}';
      if (bytes.length < 24 ||
          bytes[0] != 137 ||
          ascii.decode(bytes.sublist(1, 4)) != 'PNG') {
        throw StateError('Invalid PNG');
      }
      final old =
          previous
                  .where(
                    (entry) =>
                        entry['file'] == relative &&
                        entry['sha256'] == checksum,
                  )
                  .firstOrNull
              as Map<String, dynamic>?;
      final data = bytes.buffer.asByteData();
      captures.add({
        ...?old,
        'file': relative,
        'app': app,
        'sha256': checksum,
        'sourceRevision': old?['sourceRevision'] ?? revision,
        'sourceDigest': old?['sourceDigest'] ?? sourceDigest,
        'sourceState': old?['sourceState'] ?? 'working-tree',
        'designSystemVersion': old?['designSystemVersion'] ?? tokens['version'],
        'capturedAt':
            old?['capturedAt'] ??
            file.statSync().modified.toUtc().toIso8601String(),
        'imagePixels': {
          'width': data.getUint32(16),
          'height': data.getUint32(20),
        },
        'viewport':
            old?['viewport'] ??
            {
              'width': name.contains('desktop')
                  ? 1280
                  : name.contains('tablet')
                  ? 1024
                  : 390,
              'height': name.contains('desktop')
                  ? 800
                  : name.contains('tablet')
                  ? 1366
                  : 844,
            },
        'textScale': name.contains('-large') ? 2 : 1,
        'keyboardInset': name.contains('-keyboard') ? 320 : 0,
        'locale': name.contains('-en') ? 'en' : 'fr',
        'theme': name.contains('-dark') ? 'dark' : 'light',
        'captureKind': name.contains('components')
            ? 'production-component-composition'
            : 'production-page',
        'fixtureSource':
            'deterministic widget fixture; production widgets, no network; not a live API journey',
      });
    }
    writeJson(manifest.path, {
      'app': app,
      'designSystemVersion': tokens['version'],
      'sourceDigestInputs': inputs,
      'captures': captures,
    });
    const escape = HtmlEscape();
    File(p.join(directory, 'index.html')).writeAsStringSync(
      '<!doctype html><meta charset="utf-8"><title>EDAYA $app current UI</title><h1>Current UI</h1><a href="manifest.json">Capture provenance</a>${captures.map((entry) => '<figure><img style="max-width:100%" src="${escape.convert(entry['file'] as String)}" alt="${escape.convert(entry['file'] as String)}"></figure>').join()}',
    );
  }
}

final visualLiteral = RegExp(
  r'''(?<![\w])Colors\.[A-Za-z]+(?:\.shade\d+)?|#[0-9a-fA-F]{3,8}\b|0x[0-9a-fA-F]{8}\b|(?:bg|text|border|ring|fill|stroke)-(?:red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose|slate|gray|zinc|neutral|stone)-\d{2,3}\b|(?:rgba?|hsla?)\(\s*\d|(?:text|rounded(?:-[a-z]+)?|shadow|duration|gap|[mp][xytrbl]?)-\[[^\]]+\]|(?:fontSize|letterSpacing|elevation):\s*-?\d+(?:\.\d+)?|BorderRadius\.circular\(\s*\d+(?:\.\d+)?''',
);
